// ─────────────────────────────────────────────────────────────────────────────
// FFI host abstraction
// ─────────────────────────────────────────────────────────────────────────────
// Implemented by the consumer (e.g. a wasm-backed host or a native bridge).
// Each unary RPC sends a serialized request and receives a serialized response;
// streams are handed off to the host via openStream.
//
// `serviceName` is the bare service identifier (e.g. "VolvoxGridService").
// `methodName` is the fully-qualified gRPC method path
// (e.g. "/volvoxgrid.v1.VolvoxGridService/Create").

export interface PluginHost {
  invoke(serviceName: string, methodName: string, data: Uint8Array): Uint8Array;
  openStream(serviceName: string, methodName: string): PluginStream;
}

export interface PluginStream {
  send(data: Uint8Array): void;
  /** Returns null once the server has closed the stream. */
  recv(): Uint8Array | null;
  closeSend(): void;
  close(): void;
}

