  *generate(request: pb.GenerateRequest): Generator<pb.GenerateEvent, void, undefined> {
    const stream = this.host.openStream(
      "VolvoxAiService",
      "/volvoxai.v1.VolvoxAiService/Generate",
    );
    try {
      stream.send(request.toBinary());
      stream.closeSend();
      while (true) {
        const data = stream.recv();
        if (data == null) return;
        yield pb.GenerateEvent.fromBinary(data);
      }
    } finally {
      stream.close();
    }
  }

